async def act(page):
    """Close any blocking popup, navigate to the Sample Page if necessary,
    then locate the Archives widget and click the "December 2017" link.

    The function uses accessibility-role-centric selectors where possible,
    guards indexed locator access with await locator.count(), and leaves the
    final navigation-causing click (the archive link) as the last action.
    """

    # 1) Try to close a modal/dialog by scoped searches first
    closed = False
    dialogs = page.get_by_role("dialog")
    if await dialogs.count():
        dlg = dialogs.nth(0)
        close_names = ["Close", "close", "Dismiss", "dismiss", "×", "x", "X", "Close popup"]
        for name in close_names:
            btn = dlg.get_by_role("button", name=name)
            if await btn.count():
                try:
                    await btn.first.click()
                except Exception:
                    await btn.first.click(force=True)
                closed = True
                await page.wait_for_timeout(300)
                break

    # 2) If not closed yet, scan all buttons for likely close controls (aria-label/title/text)
    if not closed:
        btns = page.get_by_role("button")
        if await btns.count():
            total = await btns.count()
            for i in range(total):
                b = btns.nth(i)
                try:
                    aria = (await b.get_attribute("aria-label")) or ""
                except Exception:
                    aria = ""
                try:
                    title = (await b.get_attribute("title")) or ""
                except Exception:
                    title = ""
                try:
                    txt = (await b.inner_text()).strip() or ""
                except Exception:
                    txt = ""
                combined = f"{aria} {title} {txt}".strip().lower()
                if any(k in combined for k in ("close", "dismiss", "×", "x", "close popup", "dismiss popup")):
                    try:
                        await b.click()
                    except Exception:
                        await b.click(force=True)
                    closed = True
                    await page.wait_for_timeout(300)
                    break

    # 3) If still not closed, try clicking near the top-right of a visible popup body
    #    by locating its text (the screenshot shows "This is a test popup!") and
    #    clicking the top-right area of that bounding box.
    if not closed:
        popup_text = page.get_by_text("This is a test popup!")
        if await popup_text.count():
            box = await popup_text.bounding_box()
            if box:
                # Click near the top-right corner of the popup content to hit the close icon
                click_x = box["x"] + box["width"] - 8
                click_y = box["y"] + 8
                try:
                    await page.mouse.click(click_x, click_y)
                except Exception:
                    # If direct mouse click fails, try a forced click on the text as a last resort
                    try:
                        await popup_text.first.click(force=True)
                    except Exception:
                        pass
                closed = True
                await page.wait_for_timeout(300)

    # Small pause to allow UI to settle after close attempts
    await page.wait_for_timeout(200)

    # 4) Navigate to Sample Page if present (Archives widget commonly found there)
    sample_link = page.get_by_role("link", name="Sample Page")
    if await sample_link.count():
        try:
            await sample_link.first.click()
        except Exception:
            # If a normal click is blocked, force it
            await sample_link.first.click(force=True)
        # Wait briefly for navigation/load to settle
        try:
            await page.wait_for_load_state("networkidle", timeout=5000)
        except Exception:
            await page.wait_for_timeout(500)

    # 5) Search for a container with accessible name "Archives" and click the in-scope "December 2017" link
    parent_roles = ["complementary", "region", "group", "navigation", "article", "aside"]
    for role in parent_roles:
        container = page.get_by_role(role, name="Archives")
        if await container.count():
            link = container.get_by_role("link", name="December 2017")
            if await link.count():
                # This click likely navigates away; make it the final action
                await link.first.click()
                return

    # 6) If no named container, find a heading "Archives" and filter containers that contain it
    heading = page.get_by_role("heading", name="Archives")
    if await heading.count():
        for role in parent_roles:
            containers = page.get_by_role(role).filter(has=heading)
            if await containers.count():
                cont = containers.nth(0)
                link = cont.get_by_role("link", name="December 2017")
                if await link.count():
                    await link.first.click()
                    return

    # 7) Final fallback: click any visible link named "December 2017"
    direct = page.get_by_role("link", name="December 2017")
    if await direct.count():
        await direct.first.click()
        return

    # If we reach here, the target link wasn't found
    raise RuntimeError("Could not find the 'December 2017' link in the Archives widget.")

